INSERT INTO epics (slug, goal, status, status_note, close_sweep, created_at) VALUES ('adoption-contract', 'Make the materials that init installs sufficient for a fresh agent''s first hour. The generated contract describes the verbs but never says how to invoke the tool, which tracker it is operating on, what language its content should be in, or that a whole class of writes is refused against a closed epic; the migration guide documents neither the md-table format it offers nor the remote a copy-on-write rehearsal copy inherits, and the reconcile recipe covers only one of the two directions divergence can take. Every item was hit in practice during the pilot rehearsals. The task-versus-story rule this goal originally listed was delivered by epic tracking-integrity (#55) and is not scope here.', 'ACTIVE', '', '', '2026-07-25T20:18:19Z');
INSERT INTO epics (slug, goal, status, status_note, close_sweep, created_at) VALUES ('pilot-adaptation', 'Adapt selftracked to deployment on an external pilot repository: debug the onboarding recipe (init, hook colocation, legacy import) on local sandbox copies until it deploys cleanly and repeatably; file every generic defect or missing feature it surfaces as ordinary public tasks. Pilot specifics never enter tracked content - records here are worded purely in terms of what selftracked does.', 'CLOSED', '', '2026-07-25', '2026-07-25T01:04:29Z');
INSERT INTO epics (slug, goal, status, status_note, close_sweep, created_at) VALUES ('tracking-integrity', 'Make the tracker able to say where work belongs. Close the dead zone in which work that falls under an epic whose stories are all terminal can be recorded nowhere, give the detector a window that can see it, remove the advisory that reports a state no verb can clear, and make the session-start surface state the condition in words instead of a bare counter. The interactive protocol that puts the choice to the owner is v0.1; v0 stops at making the condition visible.', 'CLOSED', '', '2026-07-26', '2026-07-25T20:17:50Z');
INSERT INTO epics (slug, goal, status, status_note, close_sweep, created_at) VALUES ('v0-bootstrap', 'Build selftracked v0 per docs/v0-spec.md and switch this repository to self-hosting', 'CLOSED', '', '2026-07-24', '2026-07-18T23:39:52Z');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 1, 'A fresh agent working only from the installed materials can determine how to invoke the tool, which tracker a verb operates on, and whether new work belongs as a standalone task or a story under an epic', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 2, 'Every refusal class an adopter can meet in the first hour is named in the generated contract, the terminal-epic class among them, together with its sanctioned routes', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 3, 'The migration guide documents the md-table format it offers, and makes severing the inherited remote the first act on a copy-on-write rehearsal copy', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 4, 'The installed materials state the language of tracker content, how the tool is invoked, and the recovery path for BOTH directions divergence can take, with how to tell them apart; a fresh crew needs no knowledge from outside the repository for any of the three', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 5, 'No import path the tool offers ends in a green exit with nothing imported, and the migration guide states what a repeat or delta import does to an epic already closed and where the operator learns of it', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('adoption-contract', 6, 'One field carries one name across the verbs and the import corpus, or the mapping is stated where an adopter meets it; and a gate fails when this repository''s installed copies drift from the templates it ships', 0, '');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('pilot-adaptation', 1, 'The documented onboarding recipe deploys selftracked end-to-end (init, hooks, import) on two consecutive fresh sandbox copies with selftracked verify green and no manual forks', 1, 'runs two and three: fresh-context agents executing only the handoff reached verify green (0 violations) end-to-end with no manual forks; third run deviation-free');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('pilot-adaptation', 2, 'Import fidelity on the sandbox copy is verified by recorded checks: no source records lost or altered', 1, 'per-status task counts, story/worklog/criteria row counts equal across source prose (independent greps), derivation manifest and imported dump on every rehearsal run');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('pilot-adaptation', 3, 'Every generic defect surfaced by the experiments is filed as a public task; every fix applied carries tests and green gates', 1, 'Refreshed 2026-07-25 - the earlier evidence ("one generic defect surfaced (#19)") was true only of the first rehearsals and went stale as the epic continued. The experiments have since filed #22-#24, #26-#32, #34, #36-#47 (verb-surface and import sweeps), #50 (fixture-gate), and #51-#56 (contract gaps found by the deploy re-verification campaign); #57 is an owner question in IN-REVIEW. Fixes applied under this epic carry tests and green gates: the #19 scaffold fix with content tests (be1669e), the terminal-epic guards and R16 with their amendments (a0ac6cc). The remaining filings are open defects deliberately left for later work, which this criterion asks be FILED, not fixed.');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('tracking-integrity', 1, 'Work that fits no existing task, story or epic is surfaced by the tool''s own output at session start, in words, rather than discovered afterwards from a bare zero among counters', 1, 'PO 2026-07-26: attested on the v0 scope the owner set in #61. prime names the epic-scoped instance - an ACTIVE epic with no story that can receive work - as a typed no-workable-story notice in the JSON the SessionStart hook reads, and as a sentence in the digest. Work matching no epic at all is NOT detected by any tool output: that is the v0.1 interactive protocol (#61, parked), and this criterion''s wording is broader than v0 delivers. Attested with the narrowing on the record because no verb can edit a criterion (#65). Evidence: commit fa5dbb2; make gates exit 0.');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('tracking-integrity', 2, 'The recording dead zone is resolved: work that legitimately falls under an epic whose stories are all terminal either has a sanctioned record, or meets a refusal that names the alternative and the choice belonging to the owner', 1, 'Both refusals met in the dead zone name the routes that apply in the epic''s current state, and mark the story route as a scope change the owner authorizes. Evidence: commit db6db4b; the coordinator reproduced the WIP-slot defect before the fix and the corrected advice after; make gates exit 0.');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('tracking-integrity', 3, 'Every change to a surface the spec describes landed through an accepted OpenSpec change proposal before its code merged, with tests and green gates', 1, 'Five OpenSpec proposals written before any code, revised against a five-lens critic round, ratified by the owner 2026-07-25, applied to docs/v0-spec.md (rev 3.28 to 3.33) and re-checked by the section 2.1 delta-diff pass, which found five divergences, all fixed in 012d382. Every story closed on make gates exit 0 with a FULL-tier critic round.');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 1, 'Verb catalog, integrity engine (R1-R15), init, hooks, reader half, and import built; make gates green locally through S9', 1, 'git history: docs/v0-progress.md ledger @ 489f4c5; local gates run @ acdd980 (interim, D-EP8)');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 2, '$ selftracked verify', 1, 'PASS selftracked verify @ 2026-07-24T23:27:19Z');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 3, 'Schema version gate and migration branches ship (plan S11)', 1, 'S11 landed at commits ab10c78..32dcb18: the 8.6 gate before every verb (dispatcher + pipeline re-check), the migration engine on the load path with two hydration sources, escalation with the sentinel protocol, 8.4 branches (5)-(6), prime migrated:vK->vN; make gates exit 0 on a cleared cache 2026-07-24; FULL three-critic close review; spec revs 3.22-3.23');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 4, 'Pilot ladder rungs 3-4: gitignored disposable-clone import rehearsal, then colocated live install (plan S12)', 1, 'Rung 3: repeated from-scratch imports of the pilot corpus, verify full 0 violations each archived round, determinism by timestamp-normalized byte-identity; rung 4: colocated live install, incumbent hooks chained per recipe, host gate authoritative, verify 0 violations; docs/research/2026-07-24-pilot-import-rehearsal.md');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 5, 'README, CONTRIBUTING (DCO + AI clause), generic migration guide, docs link-check (plan S12)', 1, 'README final, CONTRIBUTING (DCO + AI clause), docs/migration-guide.md (boundary, reconciliation, both rehearsal-found authoring constraints; example round-trips through import+verify), scripts/check-doc-links.sh exit 0 - commits ab10c78..92d5fe3, reviewed by the S12 fidelity critic');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 6, 'First push: gates re-run against the squashed tree, verified rows re-stamped, CI green (D-EP11)', 1, 'CI green on the published tree (origin/main 42a3e5b): GitHub run 30132992219 success on all jobs — policy gates, macOS full suite, Ubuntu full suite, Windows dump-determinism. Published WITHOUT squash (owner decision); the tree was history-rewritten pre-push only to re-stamp evidence (ef1d4f7) and scrub the pre-publication audit findings, not squashed. Verified-by-command worklog rows S1-S19 cite story shas <=19a608f, untouched by the scrub.');
INSERT INTO epic_criteria (epic, seq, criterion, met, evidence) VALUES ('v0-bootstrap', 7, 'Spec governed proposal-first end to end: every deviation an archived amendment (26 amendments through spec rev 3.21 / plan rev 17)', 1, 'openspec/changes/ directory; amendments log in git history (docs/v0-progress.md @ d4cddcc)');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (1, 'Align dump.sql file mode with the other tracked files (0600 from CreateTemp+rename vs 0644)', 'OPEN', 'Parked at the S8a close (code critic): more restrictive, not a leak; git tracks content, not mode. internal/dump owns it if it ever matters.', '', NULL, NULL, '2026-07-23T22:09:23Z', '2026-07-24T23:27:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (2, 'Read-transaction for prime/state snapshot consistency, if the owner ever wants it', 'OPEN', 'Refuted as a defect at the S8c close under the single-writer axiom (spec section 1); a momentary off-by-a-few in advisory totals that self-heals on the next prime. Remedy on record: wrap prime/state reads in one read transaction.', '', NULL, NULL, '2026-07-23T22:09:23Z', '2026-07-24T23:27:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (3, 'dump_divergence is a boolean and cannot distinguish a behind DB from a truly divergent one', 'OPEN', 'Post-v0 note from the 2026-07-24 open-questions round (fork analysis F2, architecture critic): both cases route to load --force + re-apply; the flag carries no distinguishing detail.', '', NULL, NULL, '2026-07-23T22:09:23Z', '2026-07-24T23:27:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (4, 'Revisit the OpenSpec proposal+delta+tasks.md convention once the tool is installed', 'OPEN', 'Parked at the first-commit review: change directories hold proposal.md only; the tool is adopted but not installed, so the convention has nothing to run against yet.', '', NULL, NULL, '2026-07-23T22:09:23Z', '2026-07-24T23:27:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (5, 'First push: re-run gates on the squashed tree and re-stamp every verified row (D-EP11)', 'DONE', 'First push done 2026-07-24: origin/main at 42a3e5b, GitHub CI run 30132992219 green on all jobs. Evidence re-stamped (ef1d4f7) and criterion 6 met. Published without squash (owner decision) — verified worklog rows S1-S19 cite story shas <=19a608f, untouched by the pre-push leak scrub.', '', NULL, 'v0-bootstrap', '2026-07-23T22:09:23Z', '2026-07-24T23:26:23Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (6, 'epic show --json emits a JSON header line plus plain-text sections, not one JSON document', 'DONE', 'epic show --json emits one JSON document; fixture in epic.txtar; spec-conformant fix (6.1 --json contract)', '', NULL, 'v0-bootstrap', '2026-07-23T22:28:38Z', '2026-07-24T01:57:31Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (7, 'criteria check misdiagnoses unmet owner-attested criteria as ''a runnable criterion failed''', 'DONE', 'standalone criteria check exits 1 only for failed runnables; close still blocks on unmet attested (condition 3); fixture in criteria.txtar', '', NULL, 'v0-bootstrap', '2026-07-23T22:29:35Z', '2026-07-24T01:57:31Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (8, 'import: DUPLICATE with a later-positioned canonical refuses (forward dup_of)', 'DONE', 'Closed as a documented limitation on owner ruling 2026-07-24: docs/migration-guide.md section 3 already states the authoring constraint from the pilot rehearsal — a DUPLICATE''s canonical precedes it in the corpus, dup_of is the canonical''s corpus-order id, and a forward reference refuses. No code change ordered.', '', NULL, NULL, '2026-07-24T01:27:12Z', '2026-07-24T21:41:08Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (9, 'import --legacy: an unresolvable cited commit is accepted silently; only R5 catches it', 'DONE', 'The stored value stays verbatim — spec 6.2 mandates it so R5 can flag the typo rather than legacy: masking it. What was missing was the import-time signal: the importer now names each sha-shaped token that resolves to no commit, using the same warnf channel as the date-disagreement warning. Asserted end to end in import-typo.txtar.', '', NULL, NULL, '2026-07-24T01:28:05Z', '2026-07-24T20:30:31Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (10, 'chaining recipe: a guarded chained line would survive directory-deletion abandonment', 'DONE', 'Fixed via amendment chaining-recipe-guards-abandonment (spec rev 3.24, commit ab20d2f): both printed lines are existence-guarded, so deleting .selftracked/ no longer blocks the host repository''s commits with 127. All three cases (absent, RED, green) proven by hand before the change; activate_test.go pins the guarded lines; make gates green. (Commit sha re-stamped to the published value after the 2026-07-24 pre-push leak scrub, per D-EP11.)', '', NULL, NULL, '2026-07-24T01:49:31Z', '2026-07-24T23:29:26Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (11, 'Pre-release review pass', 'DONE', 'Fulfilled by the 2026-07-24 pre-publication work, closed on owner ruling: audit round 1 (e5ad831), the red-team self-audit dossier and privacy research (private archive, 2026-07-24), the hygiene pass recorded as task #14 (0c55ceb), and the owner-sanctioned history rewrite with evidence re-stamp (ef1d4f7). Publication to the public remote happened the same day; the go-public gate this task guarded has been passed.', '', NULL, NULL, '2026-07-24T12:56:09Z', '2026-07-24T21:05:23Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (12, 'PROMPT.md verb catalog omits gate and import; verify the deny-list claim''s wording against the live instance', 'DONE', 'Fixed in the generator: PROMPT.md''s catalog now lists gate and import (Maintenance & state), so the correction reaches every adopter, and cmd/selftracked/catalog_doc_test.go compares the generated file against the registry the binary installs, so the next omission fails the build rather than shipping. Golden regenerated. Part (b) — the settings.json deny entry — was already corrected on 2026-07-24.', '', NULL, NULL, '2026-07-24T13:01:13Z', '2026-07-24T20:27:37Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (13, 'Harden the agent push barrier (this repo)', 'DONE', 'Closed on owner ruling 2026-07-24: the control is in place — git push denied at the permission layer (.claude/settings.json deny rules, e4aa352) and the this-repo-only, no-template-change decision recorded (dd0693a). No further hardening ordered.', '', NULL, NULL, '2026-07-24T13:26:03Z', '2026-07-24T21:32:34Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (14, 'Pre-release repository hygiene pass', 'DONE', 'Completed; detail in the private research archive', '', NULL, NULL, '2026-07-24T14:21:47Z', '2026-07-24T15:11:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (15, 'Full Windows support (post-v0): hooks, symlinks, sqlite locking, path separators', 'OPEN', 'v0 targets POSIX (spec 16); Windows CI verifies only dump byte-determinism. Full support is future work. First cross-platform CI run surfaced: pre-commit hook tests fail on Windows (generated hook is POSIX sh, run directly without a shell); symlink-containment tests need Windows symlink privileges; TestGateRaceOneWinner sees different sqlite file-locking semantics; TestScripts path-separator assumptions. Scope a Windows-portability pass if/when Windows becomes a target.', 'Post-v0; v0 explicitly targets POSIX per spec 16', NULL, NULL, '2026-07-24T16:39:08Z', '2026-07-25T01:14:52Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (16, 'Argument-shape guard for dump-supplied tokens reaching git argv (verify/import-dates)', 'DONE', 'Fixed: R5 refuses a leading-dash citation before git cat-file; the import-dates git show sink was already shaShape-gated (internal/verb/import_dates.go:35, pre-existing). stale --since refuses a leading-dash revision. Red fixtures proven red without the guards.', '', NULL, NULL, '2026-07-24T20:05:41Z', '2026-07-24T20:22:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (17, 'git mv in paths move receives dictionary-supplied roots with no -- separator (CWE-88 shape)', 'DONE', 'Fixed: git mv now takes a -- separator, and paths move validates the new root like paths set does (one column, one validation). Covered by dict_root_test.go plus the existing git-transport case in paths-move.txtar.', '', NULL, NULL, '2026-07-24T20:05:41Z', '2026-07-24T20:22:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (18, 'epic show omits the linked-artifacts section (ADRs and evidence are invisible to a reader)', 'DONE', 'Fixed via amendment show-verbs-print-linked-artifacts (spec rev 3.25, commit b653b15): show <id> and epic show list linked artifacts as class[@scope]:relpath (role), archived marked, text and --json ([] when empty). link.txtar asserts it; live check: ADR 0001 now prints on this task (grounding) and on epic:v0-bootstrap (adr). (Commit sha re-stamped to the published value after the 2026-07-24 pre-push leak scrub, per D-EP11.)', '', NULL, NULL, '2026-07-24T20:44:34Z', '2026-07-24T23:29:26Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (19, 'Bookkeeping commit with an empty index refuses despite the hook staging dump/STATE', 'DONE', 'Fixed in the generated guidance: claude_rule.md and claude_skill.md templates (+ this repo''s instances and goldens) now spell the explicit staging command for the bookkeeping commit, with the why (git refuses a commit whose only content was hook-staged when the index started empty; reproduced in a scratch repo). Asserted by content tests; go test ./... 12/12 ok.', '', NULL, 'pilot-adaptation', '2026-07-25T01:25:43Z', '2026-07-25T01:28:51Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (20, 'Probe: fresh-agent working loop on an adapted host', 'DONE', 'Probe executed on a sandbox host copy: a fresh-context agent, given only the generated PROMPT.md, ran the full loop - prime, create, a file change committed through the host''s chained hook stack (host gate silent on success; selftracked printed its state-refresh and staged-refresh lines), set-status DONE with --note, explicit-staging bookkeeping commit (plain commit refused on empty index exactly as #19 documents), verify 0 violations with the advisory census unchanged, clean tree. Coordinator independently re-verified commits, task state, verify output and file content. Four PROMPT.md usability gaps surfaced; filed as a follow-up task.', '', NULL, 'pilot-adaptation', '2026-07-25T07:56:21Z', '2026-07-25T08:01:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (21, 'PROMPT.md: close the usability gaps a fresh-agent probe surfaced', 'DONE', 'Template rewritten: working-loop section (prime named as the session-start read; bookkeeping commit with explicit staging and the empty-index rationale), full verb catalog with signatures, and the task/story/epic status vocabularies with transition rules (set-status note-rewrite trap documented). Repo''s own PROMPT.md instance refreshed from the template (it predated even the gate/import fix). Evidence: go test ./... 12/12 ok incl. 8 new content assertions and the catalog honesty test; commit 4e546e2. CLI usage strings left untouched: the spec''s verb table pins signatures, so enriching them is amendment territory - PROMPT.md is where the spec says the catalog lives.', '', NULL, NULL, '2026-07-25T08:01:28Z', '2026-07-25T08:12:46Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (22, 'list --epic accepts any slug silently: unknown or epic:-prefixed slugs return 0 rows, exit 0', 'OPEN', 'A nonexistent epic slug (or the epic:SLUG form that epic list itself prints) filters to an empty result with no diagnostic - indistinguishable from an epic with no tasks. Found by the S5 read-surface sweep; epic show refuses the same input loudly.', '', NULL, NULL, '2026-07-25T08:23:47Z', '2026-07-25T08:23:47Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (23, 'criteria check prints nothing on success', 'OPEN', 'Zero bytes on stdout (plain and --json), exit 0, for an epic whose criteria are all met - a caller cannot distinguish checked-and-green from did-nothing. verify prints a summary even when clean; criteria check should say N/N met. Found by the S5 read-surface sweep.', '', NULL, NULL, '2026-07-25T08:23:47Z', '2026-07-25T08:23:47Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (24, 'Verbs never say which tracker they operate on', 'OPEN', 'A verb resolves .selftracked/ from the working directory and gives no cue in its output; with two trackers on one machine (a coordinating repo plus a sandbox host) a wrong-cwd write lands silently in the wrong database - happened once during the S5 sweep. Possibly a one-line repo identifier in write-verb output or prime; design call.', '', NULL, 'adoption-contract', '2026-07-25T08:23:47Z', '2026-07-25T20:18:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (25, 'Scaffolded divergence recipe names a verb form that always refuses', 'DONE', 'Templates and instances corrected to load --force with the discard warning and the re-apply-local-writes step; plain load''s refusal documented. Evidence: go test ./... 12/12 incl. 3 new content assertions; commit recorded in git history. P5 docs-only exception: no verb behavior touched.', '', NULL, NULL, '2026-07-25T08:42:33Z', '2026-07-25T08:43:39Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (26, 'create --help does not state the default status', 'DONE', 'Closed by story S3 2026-07-26. internal/verb/tasks.go''s usage string now reads --status OPEN|IN-REVIEW|NEEDS-TRIAGE (default NEEDS-TRIAGE), matching section 6.2''s row which is its normative source, and internal/cli/testdata/tasks-create.txtar pins it at the surface an agent actually reads. Verified live: create -h prints the parenthetical. Two adjacent defects were closed with it. The spec row itself lacked the [--json] the code prints, so the normative source did not match the string it governs; and PROMPT.md''s verb catalog stated the same default in a second, older wording, which is one fact with two homes and the shape this task was filed about. Mutation-checked: dropping the parenthetical and giving it the wrong value (default OPEN) both fail the fixture.', '', NULL, 'adoption-contract', '2026-07-25T08:53:40Z', '2026-07-26T09:29:49Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (27, '--dup-of rejects the #N id form every other argument accepts', 'OPEN', 'set-status <id> accepts #N or N; --dup-of "#74" dies with a flag parse error (exit 2), only bare integers pass. Inconsistent ref grammar within a single command. S5 block B.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T08:53:40Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (28, 'Refusal surface is split between domain messages and raw SQLite text', 'OPEN', 'Some refusals are clean domain envelopes (use-reopen, dup-chain, not-terminal); others leak raw CHECK/trigger text with SQLite error codes appended - park on a DONE task, DONE without note, LABEL transition (blocks B/C), and md-table import status-enum violations, which additionally fail to name the offending row while the importer''s own format and dup-target errors do (block G). Same surface, two message registers. S5.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T09:12:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (29, '--json silently ignored by rel add/rm/tree/cycles and paths ls', 'OPEN', 'The spec promises --json on every verb; rel add/rm/tree/cycles, paths ls/set, the epic family (list, show), and import''s success line all accept the flag and emit plain text anyway - only list and verify were observed genuinely honoring --json on the success path. Error envelopes are JSON everywhere (import errors are JSON even without the flag). Breaks scripted consumption of the documented contract. S5 blocks B, C, D, E, G.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T09:12:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (30, 'show does not surface a DUPLICATE task''s canonical', 'OPEN', 'show #N on a DUPLICATE prints only [DUPLICATE]; neither plain nor --json output carries dup_of. The one fact that status exists to record is only reachable via rel tree. S5 block B.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T08:53:40Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (31, 'list --status LABEL returns 0 rows unless --labels is also passed', 'OPEN', 'The default label-exclusion is applied before the status filter, so explicitly asking for LABEL rows yields nothing without the second flag; nothing in --help says the flags interact. S5 blocks B and C.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T08:53:40Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (32, 'rel''s usage-class refusal exits 1, not 2', 'OPEN', 'rel add X duplicates Y returns code:usage in its envelope but process exit 1 (the domain-refusal code); the spec''s three-way exit split says usage belongs to 2. Either the envelope code or the exit code is wrong. S5 block C.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T08:53:40Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (33, 'Does an archived home link satisfy R13?', 'DONE', 'R13 counts live homes only (amendment r13-counts-live-homes, spec rev 3.26). Evidence: rules_fs.go r13 joins artifacts on archived=0; two new verify tests (archived-only home flagged, live-beside-archived not flagged); go test ./... green; make gates exit 0.', '', NULL, NULL, '2026-07-25T08:53:40Z', '2026-07-25T14:45:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (34, 'Restarting the story that holds the WIP slot names itself as the blocker', 'OPEN', 'story start on the story that is ALREADY IN-PROGRESS returns the generic WIP envelope - story S1 is IN-PROGRESS, finish or block it first - about itself, instead of a distinct already-in-progress message. Misleading self-reference. S5 block D.', '', NULL, NULL, '2026-07-25T09:01:16Z', '2026-07-25T09:01:16Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (35, 'Does a CLOSED epic accept new criteria - and should verify notice an unmet one there?', 'DONE', 'Answered and implemented: a terminal epic''s closure is a claim verify re-checks (R16, amendment terminal-epic-conditions-stay-true, rev 3.27) and its record is write-locked against the verbs that reopen close conditions, with V-rows, corrections, artifact links and --detach carved out (amendment terminal-epics-refuse-reopening-writes, rev 3.28). criteria add on a terminal epic now refuses. Evidence: terminal-epic.txtar end-to-end; three R16 verify tests incl. the import exemption; go test ./... green; make gates exit 0.', '', NULL, NULL, '2026-07-25T09:01:16Z', '2026-07-25T14:45:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (36, 'Path dictionary: a mistyped class is permanent and unvalidated', 'OPEN', 'paths has no unset/remove verb, class names take any string including spaces, and re-registering a class silently drops --ephemeral/--note instead of merging. One exploratory sweep left four irremovable scratch rows. S5 block E.', '', NULL, NULL, '2026-07-25T09:12:11Z', '2026-07-25T09:12:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (37, 'paths set accepts a nonexistent root; the mistake surfaces later as RED R2', 'OPEN', 'No existence check at set time; the typo turns up as FAIL R2 on the next verify, which also bricks the pre-commit gate until fixed. Cheap to catch at the verb. S5 block E.', '', NULL, NULL, '2026-07-25T09:12:11Z', '2026-07-25T09:12:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (38, 'paths move --with-files cannot see untracked files and says the directory is empty', 'OPEN', 'The move shells out to git mv, so files not yet git add-ed are invisible and the refusal reads git mv failed: source directory is empty while the directory plainly holds files. Also asymmetric preconditions: the dictionary-only move tolerates an existing destination, --with-files demands a fresh one. S5 block E.', '', NULL, NULL, '2026-07-25T09:12:11Z', '2026-07-25T09:12:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (39, 'md-table import: a corpus with no recognized section heading imports as a silent no-op', 'DONE', 'Closed by story S2 2026-07-26. A corpus from which no row of any kind was inserted is now refused with code format, exit 1, and the rule sits at the verb rather than in a reader because both readers produce the empty corpus. Verified by the coordinating agent in a throwaway tracker, not from the implementer''s report: a bare pipe table with no heading refuses with ''no md-table section was recognized, so no row was imported'' naming the five headings md-table accepts; an empty JSON object refuses with the json equivalent naming the object keys; a corpus whose only recognized section is empty refuses with ''every md-table section in it is empty''; a paths-only corpus still imports green, exit 0, ''imported 1 path(s), 0 epic(s), 0 story(ies), 0 task(s), 0 worklog row(s)''. A repeat import still refuses for its own pre-existing path-exists reason rather than being swallowed by the new rule. The wrongly-cased heading path, which already refused loudly, is untouched. A mutation round confirmed the fixture catches removal of the refusal, inversion of the two-reason discriminator, loss of the path count, and counting the wrong subset of sections in either direction.', '', NULL, 'adoption-contract', '2026-07-25T09:12:11Z', '2026-07-26T07:57:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (40, 'md-table import: an unknown extra column is silently discarded', 'WONT-DO', 'Closed 2026-07-25 as not reproducible. Four data-losing md-table shapes were probed against the binary this task was filed against - an unknown header column, a data row with more cells than the header, a duplicate header column, and known-but-unused columns - and every one is either refused with exit 1 or preserved by folding into note. The header check against a closed per-kind vocabulary sits at internal/verb/import_mdtable.go:242-243 and predates the filing (acdd980, 2026-07-21, four days earlier). Reopen with an exact reproduction if one exists; the silent-no-op defect that IS real for md-table is #39.', '', NULL, NULL, '2026-07-25T09:12:11Z', '2026-07-25T19:19:27Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (41, 'The md-table import format is documented nowhere', 'DONE', 'Closed by story S2 2026-07-26; the documentary work landed with story S1''s application of the guide deltas and this story completed the code half it depended on. docs/migration-guide.md section 4.1 states the md-table shape where the reader meets it: that it carries no criteria section at all while it does carry worklog and future_increment, the five lower-case exact headings, the per-section column names verified against import_mdtable.go''s knownColumns, that a repeated section is refused as a duplicate, and - added in this story - that a corpus inserting nothing is refused, stated once in section 4 because the rule is format-agnostic. The ten trial-and-error iterations this task recorded were against undocumented headings and columns; both are now in the guide.', '', NULL, 'adoption-contract', '2026-07-25T09:12:11Z', '2026-07-26T07:57:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (42, 'show on a story omits dod/consumes/produces', 'OPEN', 'edit --dod writes a story field that no read verb prints: show epic:SLUG/SID omits dod, consumes and produces in both plain and --json output; the only way to read back what was just written is the raw dump. Same read-surface family as #30. S5 (observed while applying an owner-ratified DoD update).', '', NULL, NULL, '2026-07-25T11:59:54Z', '2026-07-25T11:59:54Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (43, 'Ref-prefix conventions differ per verb', 'OPEN', 'Three conventions coexist: epic show refuses the epic: prefix its own epic list prints; show/log require that same prefix for epics; list --epic takes a bare slug and silently accepts anything (the silent half is #22). An agent must remember which surface wants which form. PROMPT.md documents the grammar since the S5 fix, but the CLI inconsistency itself remains. S5 block A.', '', NULL, NULL, '2026-07-25T12:05:13Z', '2026-07-25T12:05:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (44, 'load --force announces the discard before validating the dump', 'OPEN', 'load --force prints its discard summary (task/epic/event counts) and only then validates the dump it was asked to load, so a caller whose dump is corrupt is told what was discarded before learning nothing was. Independently reproduced 2026-07-26 while re-measuring #45: ''discarding local database: 1 task(s), 0 epic(s), 1 event(s)'' followed by code refused on data line 13. Not adoption-contract scope; the ordering is a verb-output defect, not a materials gap.', '', NULL, NULL, '2026-07-25T12:11:13Z', '2026-07-26T00:45:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (45, 'The divergence recipe covers only one divergence shape, and never says how to tell them apart', 'DONE', 'Closed by story S2 2026-07-26. Both generated documents now carry the two divergence directions, the git test that selects between them (git log -1 --stat and git status --short on the dump, plus prime, which is read-only and safe while diverged), the rule that the good side is the one holding work that exists nowhere else, and the two-writer case where neither branch is safe. The database-is-good branch names dump then verify then the staged bookkeeping commit, and states the expected R1 line without scripting a state call - R1''s own message is the authority for that repair, which is what this task''s scope required. Both clobber shapes were re-measured during the critic round and the text corrected: with only dump.sql restored, dump alone clears the divergence and verify exits 0 with no R1; with STATE.md restored alongside it, R1 fires and state clears it. An earlier draft justified the R1 red with ''a checkout clobbers both'', which is false for the one-file shape - the same distinction this task''s own two rounds of re-measurement established. Content tests now bind each branch label to the recovery under it, proven by mutation: swapping the two labels, which would prescribe load --force for the case where it destroys unsynced work, fails the suite.', '', NULL, 'adoption-contract', '2026-07-25T12:11:13Z', '2026-07-26T07:57:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (46, 'The commit gate sees only the fast verify partition', 'OPEN', 'pre-commit runs verify --fast (stage0 + R4/R6-R9/R12 + R15); R1 dump divergence and R2 missing path roots are full-only, so a repository red under full verify commits cleanly - observed for both classes. The hook''s own message says ''verify RED'' as if red blocked. Meanwhile the gate''s blocking branch is empirically unreachable by construction: every fast-partition red we could provoke is already refused upstream (load --force self-validates R6 before replacing the database). Design call: widen the gate, rename the message, or document the split. S5 block F.', '', NULL, NULL, '2026-07-25T12:11:13Z', '2026-07-25T12:11:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (47, 'Run from a subdirectory, verbs recommend init instead of pointing at the root', 'OPEN', 'The CLI resolves .selftracked/ strictly against the current directory - no upward search. Standing in any subdirectory of a tracked repo, every verb refuses with ''no .selftracked/db.sqlite here; run selftracked init first'' - advice that, if followed, would CREATE a second nested tracker inside the repo. Same identity-blindness family as #24. Observed answering an owner how-do-I-use-this question.', '', NULL, 'adoption-contract', '2026-07-25T13:54:19Z', '2026-07-25T20:18:19Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (48, 'Every epic close condition can be violated after the close', 'DONE', 'Closed by the same two amendments: 13 verb paths guarded (criteria add/met, story add, every story transition incl. start''s own path, create --epic, edit --epic, reopen of a homed task, epic goal and story-field edits), and R16 detects what arrives by import or raw SQL. Evidence: terminal-epic.txtar asserts each refusal by code and message; go test ./... green; make gates exit 0.', '', NULL, NULL, '2026-07-25T14:04:51Z', '2026-07-25T14:45:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (49, 'criteria check rewrites a CLOSED epic''s acceptance record and destroys the close-time evidence', 'DONE', 'criteria check on a terminal epic is now report-only: it runs, prints results and its own ''results reported, not recorded'' line, exits 1 on failure, and writes nothing - the close-time evidence survives. Evidence: terminal-epic.txtar asserts the PASS evidence stays in the dump while the check reports FAIL; go test ./... green; make gates exit 0.', '', NULL, NULL, '2026-07-25T14:04:51Z', '2026-07-25T14:45:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (50, 'The rule-fixture coverage gate is not mechanized against the engine', 'OPEN', 'TestRuleFixtureCoverage claims ''a rule added to the engine without one is caught here rather than by a manual second pass'', but it only walks its own hand-written wantRules list: a new rule wired into verify''s stage1 with no entry there passes unnoticed. Demonstrated while adding R16 - the suite stayed green until the entry was added by hand. The engine exposes no rule inventory to compare against. Found during the terminal-epic implementation.', '', NULL, NULL, '2026-07-25T14:45:13Z', '2026-07-25T14:45:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (51, 'The generated PROMPT.md does not document the terminal-epic refusal class', 'DONE', 'Closed by story S3 2026-07-26. The generated PROMPT.md names the terminal refusal class, its code, its exit status, the writes it guards, and the closed list of what stays open - quoted from section 6.4 rather than paraphrased, and presented unnumbered because that list has grown twice and a numeral in it already went stale once. Two things a reader would otherwise get wrong are stated explicitly: the story dissolve carve-out reaches a CLOSED epic only and not a DISSOLVED one, and not an epic that arrived CLOSED through import either, because the gate it never passed is this tracker''s own; and there is no epic reopen, ever. Verified independently by a critic that raised a throwaway tracker and exercised every route by hand - all ten guarded writes refused with code terminal exit 1, all five open routes succeeded, and the import-arrived-CLOSED exclusion held. The skill got the branch and deliberately not the route list; a mustNot assertion enforces that, because a second copy of a list amended twice in two days is what goes stale next.', '', NULL, 'adoption-contract', '2026-07-25T16:42:00Z', '2026-07-26T09:29:49Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (52, 'The rehearsal recipe never tells you to sever the clone''s remote', 'DONE', 'Closed by story S2 2026-07-26; the text landed with story S1''s application of the guide deltas. docs/migration-guide.md now keeps the two halves apart rather than conflating them, on the corrected mechanism this task established: a local git clone sets origin to the source path, so a stray push from a rehearsal clone reaches no live project directly; a copy-on-write copy duplicates .git wholesale and inherits the source''s configured remote verbatim, which on a machine with cached credentials is one stray push from publishing rehearsal state. Severing the inherited remote is stated as the first act on a copy-on-write copy, with its expectation in the same form as every other step: git -C <copy> remote remove origin exits 0 and git -C <copy> remote -v then prints nothing.', '', NULL, 'adoption-contract', '2026-07-25T17:03:58Z', '2026-07-26T07:57:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (53, 'import inserts children under an epic that a verb has closed', 'DONE', 'Closed by story S2 2026-07-26 as the documentary defect it was narrowed to. The behaviour is not an oversight - the governing amendment gives the unguarded import path as the reason R16 exists - so what was missing was the warning. docs/migration-guide.md section 7.1 now states that a repeat or delta import can insert rows under an epic a verb has closed, that the seam is exactly the children-only shape while a corpus re-declaring the epic is refused epic-exists, that the result is an R16 advisory which does not stop a commit or fail verify''s exit code, and that every R16 finding names its own repair - edit --detach or a terminal status for a homed task, story dissolve for a non-terminal story.', '', NULL, 'adoption-contract', '2026-07-25T17:30:34Z', '2026-07-26T07:57:36Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (54, 'The generated contract never says how to invoke the tool', 'DONE', 'Closed by story S3 2026-07-26. The generated PROMPT.md carries a ''Running the tool'' section: the binary is selftracked with the alias strk and is expected on PATH; the two invocations that work without one are stated as shapes and never as literal paths, because section 14''s rule reaches this text - init is a verb and PROMPT.md is what it writes; and the section names the one-line check that replaces probing, selftracked prime, with the three shapes its answer can take. Mechanically enforced rather than left to review: TestGeneratedDocsCarryNoAbsolutePaths scans every generated document for an absolute-path token. Its first version missed five shapes, measured under Go RE2 by the coordinating agent - PATH=/, see:/, a tight markdown table cell, a tilde-username without a slash, and a Windows drive path, which matters because this project has a Windows CI job and that shape carries a username. All five are caught now, verified by planting each into a scratch copy, and a full scan of the generated documents flags nothing.', '', NULL, 'adoption-contract', '2026-07-25T17:30:34Z', '2026-07-26T09:29:49Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (55, 'PROMPT.md does not say when work is a task and when it is a story', 'DONE', 'Closed by story S4 of epic tracking-integrity, commit fa5dbb2. The generated contract states when new work is a task and when it is a story, that opening a story is a scope change the owner authorizes, and reconciles that rule with the drift rule the skill already shipped. This repository''s own PROMPT.md and installed skill carry the same text, byte-identical to their templates - the task was filed because this repository''s agent guessed, so a template-only change would have closed it without fixing that. Evidence: make gates exit 0; content tests pin both texts and both cross-references; cmp confirms the three root copies match their templates.', '', NULL, 'tracking-integrity', '2026-07-25T17:30:34Z', '2026-07-26T00:01:00Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (56, 'The generated contract states no language policy for tracker content', 'DONE', 'Closed by story S3 2026-07-26. The generated contract now states that tracker content is written in one language chosen once per repository, with English as the default it ships with, on this artifact''s own grounds: the dump is published and permanent, the PO: token is locale-fixed so a mixed-language tracker splits its own greppability, and a reader of a published dump should not need a second language. Stated as a default and not a prohibition, and ungated by construction - no verb refuses a non-English title and none is proposed. A critic round added one thing the first draft owed: the section now says which reasons argue for what. Two of the three argue for a single language whichever it is; only the locale-fixed token argues for English specifically. Without that, a public repository stating a language default reads as paperwork for everyone who chooses otherwise.', '', NULL, 'adoption-contract', '2026-07-25T17:30:34Z', '2026-07-26T09:29:49Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (57, 'PO: does the INSERT-path posture still hold now that verb writes are guarded?', 'DONE', 'Owner verdict 2026-07-25: R16 stays ADVISORY - the ratified INSERT-path posture is unchanged and no amendment supersedes it. The question is closed on two grounds established before the ruling. First, this was a decision rather than an oversight: openspec/changes/terminal-epic-conditions-stay-true/proposal.md:26 gives the unguarded import path as the reason R16 exists, and R16 scopes itself to verb-closed epics for exactly that case. Second, the residual advisory-versus-red choice is settled by reproduction: a red R16 could not be cleared. In a clean instance the task half clears two ways (set-status DONE, edit --detach) while the story half clears by no route at all - story dissolve, ready and done all refuse with code terminal, stories cannot be deleted, a re-import of the same story id is refused story-exists, and there is deliberately no epic reopen (spec §5.4) - so one stray import would make full verify permanently red, escapable only by raw SQL or a load --force rewind. The asymmetry that reproduction exposed is filed separately as #60; the missing operator warning in the spec and the migration guide is filed as #53.', '', NULL, NULL, '2026-07-25T17:30:34Z', '2026-07-25T20:17:10Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (58, 'An ACTIVE epic whose stories are all terminal has no route to record new work', 'DONE', 'Closed by story S2 of epic tracking-integrity, commit db6db4b. Both refusals now name the routes that apply in the epic''s current state; the dead zone still admits no write, and that limit is stated in the accepted amendment rather than papered over. Evidence: make gates exit 0; internal/cli/testdata/worklog.txtar asserts all four story statuses, the dead zone, the unknown epic, and the two reordered pipeline refusals; internal/verb/worklog_test.go asserts each clause as a whole string.', '', NULL, 'tracking-integrity', '2026-07-25T19:21:03Z', '2026-07-25T22:38:37Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (59, 'R10 cannot see off-book work inside its idle window', 'DONE', 'Closed by story S3 of epic tracking-integrity, commit 495cae6. R10 reports an ACTIVE epic with no story in a non-terminal status at once, independent of idle_days, and runs on the --fast partition; --quiet now prints a one-line advisory summary to stderr, so the condition reaches the commit boundary instead of being computed and discarded there. Evidence: make gates exit 0; internal/cli/testdata/hook-advisory-line.txtar drives a real git commit through the installed hook and observes the line; TestRuleFixtureCoverage''s R10 fixture seeds a homeless-not-idle and an idle-not-homeless epic, so deleting either trigger turns the mandatory gate red - re-run and confirmed.', '', NULL, 'tracking-integrity', '2026-07-25T19:21:03Z', '2026-07-25T23:26:02Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (60, 'R16 reports a state that no verb can clear', 'DONE', 'Closed by story S3 of epic tracking-integrity, commit 495cae6. Every R16 clause names its repair; the story clause gained one - story dissolve of a non-terminal story on an epic this tracker closed by verb. Scoped by provenance, not status: an epic that arrived CLOSED through import is silent to R16 and refuses the repair, and one fixture asserts both together because their agreement is the property. The criterion clause is named as what it now is - a state no verb writes, reachable only by raw SQL. Evidence: make gates exit 0; the coordinator reproduced the full round trip (R16 reports, the named repair runs, R16 goes silent) and the refusal of the import-arrived case, before and after the narrowing.', '', NULL, 'tracking-integrity', '2026-07-25T19:21:03Z', '2026-07-25T23:26:02Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (61, 'Interactive protocol (v0.1): the agent surfaces work that has no home and puts the choice to the owner', 'OPEN', 'Owner request 2026-07-25, scheduled for v0.1. When an agent is doing work that matches no existing task, story or epic, it must say so explicitly before its first write and present the owner with concrete options - a standalone task, a story under an epic, a new epic, or out of scope and parked - rather than working off-book. This is the resolution the dead zone in #58 actually needs: not another write route, but a prompt, which is also the only shape compatible with the rule that an implementing agent never authorizes its own scope. Two surfaces already exist to carry it: init installs a SessionStart hook in .claude/settings.json that injects prime --json at the start of every session, and the shipped skill (internal/scaffold/templates/claude_skill.md:15-24) describes the loop as prime, refine, pick from ready[], execute - a loop with NO branch for work that did not come from the backlog, which is how nearly all work arrives. OWNER DECISION: the interactive protocol is v0.1. For v0 the scope is limited to making prime say the condition out loud instead of printing a bare sprint_goals count. Prerequisites, both of which must land first or every option the agent offers is blocked: #58 (no route to record work in the ACTIVE-but-finished window) and #55 (no written rule for task versus story). Related: #59 (the detector cannot see the condition inside its window). Both the v0 prime change and the v0.1 protocol alter a specified surface, so each needs an OpenSpec change proposal before code.', 'PO 2026-07-25: the interactive protocol is v0.1 and is not tracking-integrity scope; its v0 half is #66, homed to the epic', NULL, NULL, '2026-07-25T19:45:16Z', '2026-07-25T21:45:51Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (62, 'The same field is named criterion in the import corpus and --text on the verb', 'DONE', 'Closed by story S7 2026-07-26. The criterion text is spelled text on both doors and criterion is an accepted alias on both. criteria add takes --text and --criterion as one flag rather than as a flag plus a better error, because an undefined flag dies in the dispatcher''s flag.Parse before any verb body runs - the mistyped spelling can be given a meaning but never a message. Supplying both with different values is a usage refusal on both surfaces, which is what obliges the corpus''s decoded fields to distinguish absent from present-and-empty; the verb resolves which flag was typed by fs.Visit, so --text '''' counts as present. Both refusals name the other spelling. Verified by the coordinating agent against a throwaway tracker: --text and --criterion write the same criteria list; both flags with different values refuse usage; neither flag refuses naming both; a corpus using text imports, one using criterion imports, one using both with different values refuses, and a third guess is redirected to both accepted names. The DDL is byte-equal before and after, sha 8bbb8daec5f8347b from binaries built at HEAD and at this tree, so no dump migrates and the schema version does not move.', '', NULL, 'adoption-contract', '2026-07-25T20:18:30Z', '2026-07-26T10:59:34Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (63, 'import does not apply the kebab-case slug rule to an imported epic slug', 'DONE', 'Closed by commit ac2ba8b. The kebab-case rule and the S<number> grammar are applied to every identifier a corpus introduces, in both formats, on the declared and the referenced paths, above the --legacy branch; worklog add''s positional slug passes validateText. Evidence: make gates exit 0; internal/cli/testdata/import-identifiers.txtar, which is also this repository''s first md-table test; the coordinator reproduced the hostile import before the fix and the refusal after, and separately confirmed the payload tail no longer reaches stderr. The three doors this does NOT close are #71, #72 and #73, each filed with its reasoning.', '', NULL, NULL, '2026-07-25T21:29:11Z', '2026-07-26T01:56:28Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (64, 'No reader marks a worklog row or an event that landed after the epic''s close', 'OPEN', 'epicShowFull lists worklog rows ordered by seq with no annotation against close_sweep, so a post-close row is visually indistinguishable from a pre-close episode row; a reader must compare dates by hand. Confirmed to cover two row types, not one: V-rows today, and - since the story-dissolve carve-out of amendment r16-reports-only-what-a-verb-can-clear - DISSOLVED repair rows. STATE.md''s Recent activity feed has the same shape: a post-close repair renders as the top line in the same format as ordinary in-flight work, for an epic that does not appear under Active epics at all. Reproduced on both row types, so the feed''s blindness predates the carve-out and is not caused by it. Raised 2026-07-25 by the semantics lens of the tracking-integrity plan critic round; widened by the regression lens of the S3 implementation round.', 'Not tracking-integrity scope; a reader-surface defect predating the amendments', NULL, NULL, '2026-07-25T21:29:11Z', '2026-07-25T23:16:04Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (65, 'A criterion cannot be corrected: no verb edits or removes an epic_criteria row', 'OPEN', 'criteria has exactly three subverbs - add, met, check (selftracked criteria --help, verified 2026-07-25) - and edit''s flag set covers title/note/goal/dod/consumes/produces/epic, not criteria. So a criterion whose wording turns out to overstate or misstate the acceptance it encodes is permanent: the only routes are to attest it met with evidence that narrows it, or to leave the epic uncloseable. Surfaced while adjudicating a critic finding that epic tracking-integrity''s criterion 1 is worded more broadly than its v0 scope can deliver. Note the deliberate asymmetry this sits against: criteria met is guarded on terminal epics and criteria check was made report-only there, both to protect close-time evidence - so any correction route has to respect that.', 'Not tracking-integrity scope; a criteria-surface gap the epic merely surfaced', NULL, NULL, '2026-07-25T21:33:59Z', '2026-07-25T21:33:59Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (66, 'prime states at session start that an ACTIVE epic can receive no work', 'DONE', 'Closed by story S4 of epic tracking-integrity, commit fa5dbb2. prime carries a typed no-workable-story notice in the JSON the SessionStart hook reads and renders it as a sentence in the human digest; stories.planned joined the tally so the notice''s silence is not the only signal. Evidence: make gates exit 0; a fidelity critic verified prime''s notices and verify''s R10 homeless clause agree across every story status (none, PLANNED, DONE, BLOCKED, DISSOLVED); the emitted JSON key order was checked against section 11.1''s stated field position, not the struct declaration.', '', NULL, 'tracking-integrity', '2026-07-25T21:45:51Z', '2026-07-26T00:01:00Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (67, 'The story-status vocabulary is still hand-written inline in epics.go''s auto-dissolve query', 'OPEN', 'internal/verb/epics.go writes status IN (''PLANNED'',''READY'',''BLOCKED'') as an inline SQL literal for the auto-dissolve precondition. It is a DIFFERENT subset from the non-terminal predicate that landed in internal/rules with story S2 of tracking-integrity (it excludes IN-PROGRESS deliberately), so unifying it is not a rename but a decision about how to express one vocabulary in several subsets. No amendment in the tracking-integrity batch names this file, so nothing schedules it. Raised 2026-07-25 by the amendment-fidelity lens of the S2 implementation critic round.', 'Not tracking-integrity scope; no amendment in the batch owns this file', NULL, NULL, '2026-07-25T22:27:13Z', '2026-07-25T22:27:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (68, 'Nothing asserts this repository''s generated copies stay byte-identical to their templates', 'DONE', 'Closed by story S6 2026-07-26. make gates now runs scripts/check-installed-copies.sh, which fails when any of the three installed generated documents differs byte-for-byte from the template it ships, and scripts/check-installed-copies-fixture.sh, which proves the comparison can fail before it reports that it did not. Evidence, all commands run by the coordinating agent rather than reported by the implementer: the gate against a scratch tree built from the real templates exits 0 on identity, 1 on a single appended byte in the third pair, and 1 with a missing copy - naming both drifted pairs in one run; an emptied pair table exits 1 rather than reporting zero comparisons as a pass; a symlink standing in for an installed copy with byte-identical content exits 1; a pair row containing a .. component is refused at --list, before the fixture can build anything outside its temp tree; an empty ROOT argument exits 1 while an absent one still defaults to the repository root. A fix round preceded this close: three critics under distinct lenses found the empty-table and symlink holes, an escape from the fixture''s own sandbox, and a false count in the amendment''s text. make gates exits 0; verify full reports 0 violations.', '', NULL, 'adoption-contract', '2026-07-25T23:40:13Z', '2026-07-26T07:02:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (69, 'R10''s idle clock reads a never-worked epic as infinitely idle', 'OPEN', 'R10''s idle trigger compares COALESCE((SELECT MAX(w.date) FROM worklog w WHERE w.epic = e.slug AND w.corrects IS NULL), '''') against the cutoff, so an epic that has never had a worklog append at all - the empty string - sorts below every cutoff and is reported idle from the moment it becomes ACTIVE. Reproduced 2026-07-26 on this repository: adoption-contract was activated the same day, holds five PLANNED stories and zero worklog rows, and verify reports ''epic adoption-contract is idle (no active story, no append in 14 days)''. The wording states a neglect that has not happened. The behaviour predates the tracking-integrity epic - the same COALESCE stood in the pre-amendment query - but it was invisible until R10 joined the --fast partition, so it now prints on every commit through the --quiet advisory line. The epics table carries created_at, which is what a never-worked epic''s clock should plausibly run from; that is a design call, not part of this record. Filed by the coordinating agent, who met it on the commit that refined adoption-contract.', 'Not adoption-contract scope; an R10 clock defect the epic merely surfaced', NULL, NULL, '2026-07-26T00:45:50Z', '2026-07-26T00:45:50Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (70, 'edit reports success while silently dropping --title on a story ref', 'OPEN', 'edit epic:SLUG/SID --title T alone refuses cleanly ("editing a story takes --dod/--consumes/--produces", code usage, exit 1). But combined with a flag the story branch DOES handle, the refusal never fires: editStoryFields writes only dod, consumes and produces, so edit epic:SLUG/SID --title T --dod D exits 0, prints "edited", changes the DoD and drops the title without a word. Reproduced 2026-07-26 in a sandbox, and met first for real on this repository''s own adoption-contract/S5, where the coordinating agent believed a story had been retitled and it had not. The guard is a no-recognised-flag check where it needed to be a no-unrecognised-flag check. Same family as #29 (flags accepted but ignored) and sharper than it: this one reports success on a partial write, so a caller reading the exit code learns nothing. Homed here because it is a first-hour trap of the same class as #22 and #31 - a green exit that did not do what was asked - and because this epic already owns the vocabulary-consistency criterion. DETACHED 2026-07-26 by the coordinating agent. The homing rationale was thin and a critic caught it: this epic''s criterion 6 is about one FIELD carrying one NAME across two surfaces, which is #62; #70 is a verb honouring some flags and silently dropping others while reporting success - the family of #29, not of #62. Covering it here would have meant widening a criterion to fit a task rather than the reverse, on an epic the owner has already ruled must stay small enough to close. It stands as a standalone task.', 'A silent-partial-write defect of #29''s family; not adoption-contract scope', NULL, NULL, '2026-07-26T00:49:21Z', '2026-07-26T02:23:26Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (71, 'A saturating story id poisons story add for that epic forever', 'OPEN', 'Section 4 says story ids are S<number> and states no bound on the number, so S9223372036854775807 satisfies the grammar and, since #63, passes import''s verb-layer check. storyAdd derives the next id with MAX(CAST(substr(id,2) AS INTEGER)) + 1, which overflows to a float: after importing such an id, story add on that epic dies with ''sql: Scan error ... converting driver.Value type float64 ("9.223372036854776e+18") to a int64'', exit 2 - an infrastructure failure, not a refusal, and the epic can never take another story. Measured 2026-07-26 by the agent implementing #63, which deliberately did not bound the digit count because the spec states no bound; the fix is a decision about whether the grammar gains one or the id generator stops trusting arithmetic. Adjacent, unmeasured: the same CAST rides internal/rules'' StoryToOffer ordering.', 'Not adoption-contract scope; a section 4 grammar question the #63 fix surfaced', NULL, NULL, '2026-07-26T01:33:02Z', '2026-07-26T01:33:02Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (72, 'load seats an identifier no verb would accept; the shape rule needs a detection half', 'OPEN', 'Empirically demonstrated 2026-07-26 by the security lens of the #63 round: hand-append an INSERT with a hostile epics.slug to a dump, run load --force - exit 0, no error - and prime --json returns the payload verbatim in epics_backlog, i.e. straight into the channel the SessionStart hook injects. ADJUDICATED, and deliberately NOT fixed inside load: section 8.5 defines load''s security boundary as the byte-equal DDL check, the token-shape whitelist grammar, the hardened pragmas, the required meta rows and the DB-only rule set - the parser is the boundary against EXECUTION, not against content, and identifier shape is nowhere in that list. Adding a shape check to load would also break R1 on any repository that already holds such an identifier, because R1 loads the tracked dump in memory and requires it to round-trip. The coherent placement is section 1.1''s own split: the verb layer stops accidents (that is what #63 did), detection handles adversaries - so this wants a verify rule over epics.slug and stories.id, which is a section 7 change and therefore travels the amendment flow. Filed rather than done: it is not adoption-contract scope and it needs a proposal first.', 'Needs a section 7 amendment first; not adoption-contract scope', NULL, NULL, '2026-07-26T01:42:13Z', '2026-07-26T01:42:13Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (73, 'The identifier grammar has no length bound, so a valid slug can flood the session-start channel', 'OPEN', 'Measured 2026-07-26 by the security lens of the #63 round: a single-word slug of 200000 ''a'' characters satisfies slugShape, imports with exit 0, and makes prime --json a 204316-byte payload - the exact channel a SessionStart hook injects into an agent''s context. The content-shape rule #63 added blocks injection SYNTAX (no spaces, no punctuation, no newlines) but not volume. Section 4 states no bound on either an epic slug or a story id, so introducing one is a grammar change and travels the amendment flow, not the fix flow. WIDENED 2026-07-26 by the coordinating agent while verifying the #63 fix: #63 bounded the three GRAMMAR refusals, but the refusal a second import of the same slug meets - code epic-exists - is a different path and still echoes the identifier whole. Measured: 195.5 KB on stderr from one refusal. So the flood reaches an agent''s context by two doors, the stored value through prime and the refusal text through any verb that names a slug back; a bound on the grammar closes both, bounding refusals one at a time does not. Related: #71, where an unbounded story-id NUMBER overflows story add''s arithmetic - the same missing-bound family reached from the numeric side.', 'Needs a section 4 amendment first; not adoption-contract scope', NULL, NULL, '2026-07-26T01:42:13Z', '2026-07-26T01:56:02Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (74, 'PO: autonomy granted for the adoption-contract epic and the flow after it', 'DONE', 'Owner verdict 2026-07-26: the coordinating agent works autonomously - it finishes the epic in progress and proceeds to the next through the established development flow, without putting each step to the owner. Where it meets what looks like a blocker, it researches the question to its primary sources first; if the research dissolves the blocker or leaves exactly one defensible resolution, the agent adopts that resolution itself rather than escalating. Scope: this session, and work inside the established flow. The grant does NOT authorize publishing - pushing stays the owner''s act alone - and does not relax the critic protocol, whose reviews still report rather than fix. Recorded because section 6.2 fixes the convention that an owner verdict living only in chat does not exist, and because this grant, not plan D-EP14, is the ratifying authority the eight adoption-contract amendments cite (spec revisions 3.34-3.41): D-EP14''s standing pre-authorization covers the v0 bootstrap window only and lapsed when epic v0-bootstrap closed on 2026-07-24.', '', NULL, NULL, '2026-07-26T06:26:44Z', '2026-07-26T06:27:03Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (75, 'Both spec-ahead notices come out when the last of the eight amendments lands', 'OPEN', '', '', NULL, 'adoption-contract', '2026-07-26T06:30:44Z', '2026-07-26T06:32:39Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (76, 'The salt file''s creation is specified by its outcome but not by its mechanics', 'OPEN', '', '', NULL, 'adoption-contract', '2026-07-26T06:30:44Z', '2026-07-26T06:32:39Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (77, 'The upward walk stops only at the filesystem root, so it can name an unrelated ancestor', 'OPEN', '', '', NULL, 'adoption-contract', '2026-07-26T06:30:44Z', '2026-07-26T06:32:39Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (78, 'CI does not run the installed-copy drift gate, so it catches drift only for whoever types make', 'DONE', 'Closed 2026-07-26 by adding the step to the policy job of .github/workflows/ci.yml - the fixture first, then the comparison, mirroring make check-copies. Scope of the fix stated honestly: CI still does NOT call make gates. Its gates job remains a hand-rolled subset (verified 2026-07-26 by parsing the workflow: checkout, setup-go, build, vet, test, lint, modern idiom, vulnerabilities - no check-pins, no binaries, no check-copies), and the policy job still enumerates scripts individually. What changed is that the installed-copy drift check now runs on every commit that reaches CI rather than only for whoever types make locally, which was the half of the amendment''s purpose this task named. The larger question - whether CI should call make gates instead of re-implementing it, so the two cannot drift - is untouched and is not this task. Verified before closing: the workflow still parses and the new step appears in the policy job''s step list; git records both scripts as mode 100755, so the checkout gets them executable; both parse and run to completion under dash, which is /bin/sh on the ubuntu runner.', '', NULL, 'adoption-contract', '2026-07-26T06:42:03Z', '2026-07-26T07:04:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (79, 'scripts/check-doc-links.sh is a gate that nothing runs', 'OPEN', 'Found by the S6 implementer, verified by the coordinating agent 2026-07-26: a repository-wide grep finds exactly one reference to the script outside the file itself - docs/stage-openings/s12.md:106, a historical record of one manual run. Neither the Makefile nor .github/workflows/ci.yml invokes it. Filed standalone rather than under adoption-contract: that epic is about the materials init installs, and this is about this repository''s own gate battery. Related to the CI observation filed alongside it, and to the same principle the drift amendment states - a check nobody is obliged to run is not a gate.', '', NULL, NULL, '2026-07-26T06:42:03Z', '2026-07-26T06:42:03Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (80, 'The drift gate''s regular-file check tests the last path component only', 'OPEN', 'Raised by the S6 fix implementer as a self-declared residual gap and verified by the coordinating agent 2026-07-26. The gate refuses a pair whose installed or template side is itself a symlink, but a symlinked PARENT directory passes: making .claude a link to a real directory holding identical files leaves the gate at exit 0 with three ok lines. Deliberately not fixed inside story S6 - it was outside the adjudicated fix list, and an implementer that widens its own list is the thing the working contract forbids. Priority is low on measured grounds rather than assumed ones: reproduced in a clean git repository 2026-07-26, replacing a tracked file''s parent directory with a symlink shows as '' D d/f.txt'' plus an untracked '' d'' entry in git status - louder than the file-level symlink case, which shows as a single typechange ''T''. So git already surfaces this one; the gate merely does not add a second line of defence for it.', '', NULL, 'adoption-contract', '2026-07-26T07:02:11Z', '2026-07-26T07:02:11Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (81, 'CI re-implements make gates by hand instead of calling it, so the two can drift', 'OPEN', 'Surfaced while closing #78 on 2026-07-26 and verified the same day by parsing .github/workflows/ci.yml: the job named ''gates'' runs checkout, setup-go, build, vet, test, lint, modern idiom and vulnerabilities - it does not run check-pins, binaries or check-copies, all of which are prerequisites of the Makefile target it is named after. The policy job picks up check-pins, probe-gofix and now the installed-copy drift check as individually enumerated scripts. So ''make gates is green'' and ''CI is green'' are two different assertions, and a step added to one does not reach the other - which is how #78 came to exist at all. Filed standalone rather than under adoption-contract: that epic is about the materials init installs, and this is about this repository''s own gate wiring. Related to #79, the gate script nothing runs.', '', NULL, NULL, '2026-07-26T07:04:20Z', '2026-07-26T07:04:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (82, 'A review agent wrote into this repository''s tracker despite a read-only brief', 'OPEN', 'Incident 2026-07-26. A critic running the standing security lens on story S2 reported that its shell cwd reset between calls, so commands it intended for its sandbox ran against the repository instead. It created stray files, which it removed, and - not noticed by it - ran import against the repository''s own tracker, inserting a path_dictionary row (''x'',''y'') whose root was two invalid bytes stored as U+FFFD. Detected by the coordinating agent from git diff HEAD on the dump, not from the critic''s own report, which mentioned only the files. Repaired by the sanctioned route, because the paths verb has no remove subverb (ls, set, move only): restore the tracked pair from HEAD, load --force to rebuild the database from it, then re-apply the two legitimate transitions the rollback also discarded. Verified after: paths ls shows the five legitimate rows, verify full reports 0 violations, and git diff HEAD on the dump shows only the intended S2 records. Two things this changes going forward. First, a critic brief that says ''sandbox your execution'' is not sufficient when the harness can reset cwd between calls - the brief must require absolute paths for every command that writes. Second, the repository''s own tracker has no verb that can delete a path row, so any accidental insertion is repairable only by a dump rollback that discards every uncommitted write alongside it.', '', NULL, NULL, '2026-07-26T07:44:20Z', '2026-07-26T07:44:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (83, 'import silently replaces invalid UTF-8 in a corpus value instead of refusing it', 'OPEN', 'Found by the standing security lens on story S2, 2026-07-26, and confirmed by the incident it caused in the same session: a corpus carrying raw invalid bytes in a string value imports green, with the bytes stored as U+FFFD replacement characters. The row that reached this repository''s tracker by accident had a root of two such characters. Pre-existing behaviour, not introduced by S2 - Go''s conversion of []byte to string substitutes rather than errors, and nothing in the import path validates encoding. Worth deciding deliberately: the tracker''s dump is a text file under git and its determinism is a gate, so what enters it should be what the operator wrote or a refusal, not a silent substitution.', '', NULL, NULL, '2026-07-26T07:44:20Z', '2026-07-26T07:44:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (84, 'import --file pointed at a FIFO blocks forever', 'OPEN', 'Found by the standing security lens on story S2, 2026-07-26, reproduced: import --file <fifo> --format json with no writer on the pipe was still running after three seconds and had to be killed. os.ReadFile has no non-blocking open, no timeout and no file-type check. Pre-existing and not introduced by S2, but every path that story added runs downstream of it. Low exploitability - the operator names the file - but a verb that hangs with no output is the worst shape a refusal can take, and the same read is the one an unbounded-size corpus goes through.', '', NULL, NULL, '2026-07-26T07:44:20Z', '2026-07-26T07:44:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (85, 'The md-table reader recognizes section headings inside fenced code blocks', 'OPEN', 'Found by the standing security lens on story S2, 2026-07-26, reproduced: a fenced illustrative example containing a heading and a table is parsed as a real section and its rows reach an insert attempt. splitSections does not track fence state. Pre-existing. Consequence today is bounded because the new empty-corpus rule reuses the same splitSections, so the main parse and the refusal-message logic are fooled identically and the corpus still refuses - but with the wrong message, saying every section was empty where nothing real was recognized. The sharper case is a guide or README pasted as a corpus by mistake: its illustrative tables would import as data.', '', NULL, NULL, '2026-07-26T07:44:20Z', '2026-07-26T07:44:20Z');
INSERT INTO tasks (id, title, status, status_note, parked, dup_of, epic, created_at, updated_at) VALUES (86, 'A write verb takes no path, so no brief instruction can stop it hitting the wrong tracker', 'OPEN', 'Second incident of the class filed as #82, on the same day, with the mitigation #82 recommended already in force. Facts, all measured 2026-07-26 before the repair: this repository''s .selftracked/db.sqlite reached 61325312 bytes and dump.sql 78858557 bytes across 305886 lines, against 879 lines at HEAD; the injected rows were 5006 synthetic epics named epic1, epic10, epic100 and so on, a load-testing corpus; the events trail ended at seq 350, my own story start, with no import events, so the rows entered through load rather than import. Repaired the same way as #82 - restore the tracked pair from HEAD, load --force, re-apply the two legitimate transitions - and verify is green again. The point is not the repair but why the guard failed. Every critic brief in this round carried, verbatim, the instruction #82 produced: use absolute paths in every command, never run a selftracked write verb against this repository''s tracker. It did not help, and it structurally cannot, because a verb resolves .selftracked/ against the process''s working directory (section 6.1) and load --force names no path at all. There is no argument in that command to make absolute. An agent whose working directory silently reset therefore issues a command that is correct as written and lands on the wrong tracker, with nothing in the command text to reveal it. So the mitigations that could work are of a different kind: a way to pin the target tracker explicitly, or an output that names which tracker was written - which is exactly what story S4 and task #24 are about, now with an incident behind them rather than an argument.', '', NULL, NULL, '2026-07-26T10:58:15Z', '2026-07-26T10:58:15Z');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S1', 'Amendments first: the spec deltas this epic needs, and the two design forks it must put to the owner', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). One OpenSpec change directory per amended surface exists under openspec/changes/, each naming its target sections, its why, what changes and the consequences accepted; the two design forks this epic cannot decide for itself - how a verb names the tracker it serves (#24), and whether verb resolution walks upward or only points at the root it found (#47) - are researched to the point where a branch is forced or a recommendation is defensible, written into their proposals with every rejected branch recorded, and DECIDED by the coordinating agent under the owner''s 2026-07-26 grant of autonomy, which supersedes this DoD''s original clause carrying them to the owner; every accepted delta is applied to docs/v0-spec.md by hand with the revision bump and history line; a fresh-context critic diffs the applied spec text against each proposal and reports no divergence; make gates exits 0', 'docs/v0-spec.md 6.1, 6.2, 7, 10, 11.1, 11.2, 11.3; docs/migration-guide.md; tasks #24 #26 #39 #41 #45 #47 #51 #52 #53 #54 #56 #62 #68', 'openspec/changes/<name>/proposal.md per amendment; the amended docs/v0-spec.md; the two forks, written for the owner', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S2', 'The rehearsal recipe stops a stray push, and the guide documents the format it offers', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). The migration guide makes severing the inherited remote the first act on a copy-on-write rehearsal copy and says why, and states the different, weaker risk a local clone carries, without conflating them; the md-table format it offers is documented where the reader meets it - its section headings, its column names, that it carries no criteria section while it does carry worklog and future_increment; a corpus with no recognized heading no longer imports as a silent green no-op; the guide warns that a repeat or delta import can reopen the conditions an epic was closed on, and names R16 and its repair as where the operator learns of it; the divergence recipe tells the reader how to decide which side is authoritative and names the dump-plus-state pair for the case where the database is the good side; make gates exits 0; #52 #41 #39 #53 #45 close with the commands as evidence', 'docs/migration-guide.md; internal/verb/import_mdtable.go; internal/scaffold/templates/PROMPT.md and claude_skill.md; the accepted amendments from S1', 'the amended migration guide; the md-table no-op refusal and its fixtures; the two-sided divergence recipe', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S3', 'The installed contract answers a fresh agent''s first hour without probing', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). A fresh agent working only from what init installed can determine how to invoke the tool without probing its environment; the terminal-epic refusal class is named in the generated contract together with its sanctioned routes (a V-row, a correction row, and - since the r16 amendment - story dissolve of a non-terminal story on a verb-closed epic); the contract states the language tracker content is written in and why; create --help states which status is the default; content tests pin every new text in the templates AND this repository''s own copies stay byte-identical to them; make gates exits 0; #54 #51 #56 #26 close with the commands as evidence', 'internal/scaffold/templates/PROMPT.md and claude_skill.md; internal/verb/tasks.go usage strings; this repository''s PROMPT.md and .claude/skills/selftracked/SKILL.md; the accepted amendments from S1', 'the contract''s invocation, refusal-class and language sections; the corrected create --help; content tests', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S4', 'A verb says which tracker it is operating on, and never advises creating a second one', 'PLANNED', 'Review tier: FULL (plan section 5, D-EP7). A write verb''s output identifies the tracker it wrote to, by whatever shape the owner ratified in S1''s fork; run from a subdirectory of a tracked repository, no verb advises init - it names the root it found, or resolves against it, per the owner''s ratified choice; a test proves the subdirectory case cannot produce advice that would create a nested second tracker; make gates exits 0; #24 and #47 close with the commands as evidence', 'internal/verb/pipeline.go; internal/cli/dispatch.go; internal/verb/prime.go; the owner''s verdict on S1''s two forks', 'the tracker-identity surface and the subdirectory resolution, with their fixtures', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S5', 'One name per field, and a guard that keeps the shipped materials and this repository''s copies identical', 'DISSOLVED', 'Review tier: FULL (plan section 5, D-EP7). The field the verbs call --text and the import corpus calls criterion has one name across both surfaces, or the generated materials state the mapping where an adopter meets it; whichever route is taken, the surface that changes keeps a refusal that names the other spelling, so an adopter who learned the old one is redirected rather than stopped; make gates exits 0; #62 closes with the commands as evidence', 'internal/verb/criteria.go; internal/verb/import.go; internal/scaffold/; the Makefile''s gate battery; the accepted amendments from S1', 'the unified field name or its documented mapping, with the redirecting refusal', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S6', 'A gate fails when the shipped materials and this repository''s copies drift apart', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). A gate step fails when this repository''s PROMPT.md, installed skill or rules file differs from the template it was generated from, so the drift that produced #55 cannot recur silently; the step runs inside make gates, not as a separate ritual; a fixture proves it fails on a planted one-character divergence and passes on identity; make gates exits 0; #68 closes with the commands as evidence. EXECUTED FIRST in this epic: stories S2 and S3 both edit the templates this guard watches, and a guard installed after them checks only what already happened.', 'the Makefile''s gate battery; internal/scaffold/templates/; this repository''s PROMPT.md, .claude/skills/selftracked/SKILL.md and .claude/rules/selftracked.md; the accepted amendment from S1', 'the template-drift gate step and its fixture', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('adoption-contract', 'S7', 'One name per field across the verbs and the import corpus', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). The field the verbs call --text and the import corpus calls criterion has one name across both surfaces, or the generated materials state the mapping where an adopter meets it; whichever route is taken, the surface that changes keeps a refusal naming the other spelling, so an adopter who learned the old one is redirected rather than stopped; make gates exits 0; #62 closes with the commands as evidence', 'internal/verb/criteria.go; internal/verb/import.go; internal/scaffold/templates/; the accepted amendment from S1', 'the unified field name or its documented mapping, with the redirecting refusal', '');
