INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('pilot-adaptation', 'S6', 'Re-verify the deploy path against the amended binary, and re-audit the backlog it produced', 'DONE', 'The full deploy path (install, import, fidelity recount, hook chaining) is re-run on a fresh sandbox copy against the current binary by fresh-context agents; the three ratified amendments are probed against imported legacy data; every finding is filed as a generic public task after a confidentiality pass; and every open record the epic produced is re-probed empirically, with the ones that no longer hold corrected or closed.', '', '', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('tracking-integrity', 'S1', 'Amendments first: the spec deltas this epic needs, written and applied before any code', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). One OpenSpec change directory per amended surface exists under openspec/changes/ with a proposal naming its target sections, its why, what changes, and the consequences accepted; every accepted delta is applied to docs/v0-spec.md by hand with the revision bump and history line; a fresh-context critic diffs the applied spec text against each proposal and reports no divergence; make gates exits 0', 'docs/v0-spec.md 5.7, 6.2, 7, 11.1, 11.3; docs/v0-execution-plan.md 2.1 and 9; tasks #55 #58 #59 #60 #61', 'openspec/changes/<name>/proposal.md per amendment; the amended docs/v0-spec.md', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('tracking-integrity', 'S2', 'The dead zone''s refusals name the sanctioned routes and who authorizes them', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). In the window where an ACTIVE epic''s stories are all terminal, each refusal an agent meets while trying to record work names the routes that actually apply in the epic''s current state and marks the story route as a scope change the owner authorizes; a script test asserts each refusal''s text and exit code in both the dead-zone state and a state where a non-terminal story exists; make gates exits 0; #58 closes with the commands as evidence', 'internal/verb/worklog.go; the accepted amendment from S1', 'refusal texts that name the routes; their script-test fixtures', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('tracking-integrity', 'S3', 'The detectors see the condition, and report only states a verb can clear', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). R10 reports an ACTIVE epic that has no story able to receive work at once, independent of idle_days, and the condition reaches the commit boundary rather than being swallowed there; R16 reports no state that no verb can clear; the story-status vocabulary the change tests against has one source of truth shared by every reader; every new branch ships a red fixture that fails without the change, and every fixture whose assertion the change reverses is rewritten rather than deleted; make gates exits 0; #59 and #60 close with the commands as evidence', 'internal/verify/rules_fs.go; internal/verify/verify.go; internal/verify/verb.go; internal/verb/stories.go; internal/verb/terminal_epic.go; internal/scaffold/templates/hooks/pre-commit; internal/cli/testdata/terminal-epic.txtar; the accepted amendments from S1', 'the amended R10 and R16 with their fixtures', '');
INSERT INTO stories (epic, id, title, status, dod, consumes, produces, blocked) VALUES ('tracking-integrity', 'S4', 'The session-start surface states the condition in words, and the contract says where new work goes', 'DONE', 'Review tier: FULL (plan section 5, D-EP7). prime carries a typed notice for an ACTIVE epic that can receive no work, in both the JSON contract the session-start hook reads and the human digest, where it renders as a sentence rather than a bare counter, and the stories tally stops hiding PLANNED; the generated contract states when new work is a task and when it is a story, that opening a story is a scope change the owner authorizes, and reconciles that rule with the drift rule already shipped in the skill; this repository''s own PROMPT.md and installed skill carry the same text as the templates they were generated from; content tests assert the template texts and the prime string-field guard classifies every new field; make gates exits 0; #66 and #55 close with the commands as evidence', 'internal/verb/prime.go; internal/scaffold/templates/PROMPT.md; internal/scaffold/templates/claude_skill.md; the accepted amendments from S1', 'prime''s notice field and digest wording; the contract''s task-versus-story rule in the templates and in this repository''s own copies; content tests', '');
