INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 1, 'S5', '2026-07-26T00:49:09Z', 'DISSOLVED', '', '', '', NULL, 'Retitled by re-cutting: the drift guard this title claimed moved to its own story S6, which must execute first because S2 and S3 edit the templates it watches. A story title cannot be edited - edit takes --dod/--consumes/--produces on a story ref - so the honest route is a dissolved record of the restructure rather than a title that over-claims. Replaced by S7.');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 2, 'S1', '2026-07-26T01:56:45Z', 'IN-PROGRESS', '', '', '', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 3, 'S1', '2026-07-26T06:31:57Z', 'DONE', 'c5d5173..7faf881', 'make gates exit 0 (build, vet, test -race all packages, golangci-lint 0 issues, fix-check clean, govulncheck clean, check-pins, binaries); selftracked verify full: 0 violations, 44 advisory', 'FULL tier. Four fresh-context critics, non-overlapping lenses, run in parallel: delta fidelity over proposals 1-4, delta fidelity over proposals 5-8, spec internal coherence, and the standing security-and-publication lens. Publication facet clean - no secrets, no machine or author identifiers, no absolute paths, no non-English text, no pilot reference. Seven blocking or material findings adjudicated. Refuted: three findings reporting that the amendments'' code deliverables were unapplied - this story''s DoD applies deltas to docs/v0-spec.md only and the code is the epic''s remaining stories; and four security findings about the two unimplemented mechanisms, held to be implementing-story decisions and filed as #76 and #77. Upheld and fixed in this story: the section 6.1 instance-digest clause contradicted the same paragraph''s no-file-content guarantee and was unsatisfiable for every verb but prime (amendment revised, spec 3.41 to 3.42); no signal distinguished spec-ahead-of-code text, with the migration guide explicitly promising the opposite while showing an example the shipped importer refuses; the salt was described as per-machine and with no random source specified; section 14 was paraphrased wider than it reads and section 2 lacked an entry for Instance. Governance defect found by the coordinating agent before the round: the applier cited plan D-EP14 as ratifying authority, which covers the v0 bootstrap window only and lapsed 2026-07-24 - replaced in all eight proposals and the spec, and the actual grant recorded in the trail as #74.', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 4, 'S6', '2026-07-26T06:32:16Z', 'IN-PROGRESS', '', '', '', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 5, 'S6', '2026-07-26T07:03:03Z', 'DONE', '8d28dfe..7b12738', 'make gates exit 0 (now including check-copies: the red fixture then the byte-for-byte comparison); selftracked verify full: 0 violations. Gate proven by the coordinating agent against a scratch tree, not by the implementer''s report: identity 0; one appended byte in the third pair 1; missing copy 1, both drifted pairs named in one run; emptied pair table 1; symlink with identical content 1; a .. row refused at --list; empty ROOT 1, absent ROOT 0.', 'FULL tier. Three fresh-context critics under distinct lenses: shell correctness and robustness, gate design and fixture non-vacuity against section 16''s three normative properties, and the standing security-and-publication lens. Publication facet clean - the only non-ASCII byte in either script is U+2014, no paths, hostnames or non-English text. Non-vacuity independently established: five separate neuterings of the gate were each caught by the unmodified fixture, and a fourth pair row added to a gate copy was picked up by the untouched fixture, so the pair list is data. Byte-exactness held against trailing-newline, CRLF and NUL-byte variants. No critic could construct a case where a real divergence inside a well-formed table goes undetected. Six defects adjudicated as real and fixed in a second round, then re-verified by the coordinating agent. One critic finding was refuted by experiment: the symlink swap was argued to be a stealthy one-line diff, but a clean git repository reports it as a typechange, so the severity was reduced while the fix was kept. The amendment''s own false count was corrected with the code. Three residual items filed with homes rather than absorbed: #78, #79, #80.', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 6, 'S2', '2026-07-26T07:43:36Z', 'IN-PROGRESS', '', '', '', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 7, 'S2', '2026-07-26T07:57:57Z', 'DONE', '6e01c3d..e224763', 'make gates exit 0 (build, vet, test -race all packages, golangci-lint 0 issues, fix-check clean, govulncheck clean, check-pins, check-copies, binaries); selftracked verify full: 0 violations. Refusals reproduced by the coordinating agent in a throwaway tracker: bare pipe table exit 1 with the nothing-recognized message; empty JSON object exit 1 with its json equivalent; all-sections-empty corpus exit 1 with the recognized-but-empty message; paths-only corpus exit 0 with a non-zero path count; repeat import still refused by the pre-existing path-exists rule.', 'FULL tier. Four fresh-context critics under distinct lenses: import-rule fidelity and Go correctness, generated text and the migration guide, test adequacy by mutation, and the standing security-and-publication lens. The import rule survived its hardest attack - a trace of all five insert paths found no shape where rows parse but nothing is inserted - and the counts line matches the spec character for character. Five defects upheld and fixed, then re-verified by the coordinating agent: the content tests asserted branch labels and branch commands independently, so swapping the two labels produced a text prescribing the destructive recovery for the case that destroys work while all 23 assertions passed; the recovery''s own bookkeeping commit was pinned only by a paraphrase while its literal also appeared elsewhere in the file, so deleting it from the recipe survived a regenerated golden; PROMPT.md''s fence committed before disclosing the R1 repair; the R1 justification was false for a single-file clobber; and the format-agnostic empty-corpus rule sat in the md-table subsection. Both mutations were re-run by the coordinating agent against a scratch copy and now fail with the right diagnosis. Refuted: the second decode on the refusal path was probed for disagreement with the first (duplicate keys, BOM, invalid UTF-8) and none was found. INCIDENT during the round: a critic''s shell lost its working directory and its import ran against this repository''s own tracker, inserting a junk path row; detected from the dump diff rather than from its report, repaired by restoring the tracked pair and load --force since the paths verb has no remove subverb, and filed as #82. Three pre-existing security findings filed: #83, #84, #85.', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 8, 'S3', '2026-07-26T08:38:46Z', 'IN-PROGRESS', '', '', '', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 9, 'S3', '2026-07-26T09:30:08Z', 'DONE', 'e224763..0508e92', 'make gates exit 0 (build, vet, test -race all packages, golangci-lint 0 issues, fix-check clean, govulncheck clean, check-pins, check-copies, binaries); selftracked verify full: 0 violations. create -h prints (default NEEDS-TRIAGE), verified live.', 'FULL tier. Three fresh-context critics: spec fidelity of the generated text, test adequacy by mutation, and the standing security-and-publication lens. The generated text itself was found faithful - the fidelity critic raised a throwaway tracker and exercised every route by hand: ten guarded writes refused with code terminal exit 1, five open routes succeeded, the import-arrived-CLOSED exclusion held. Publication facet clean: no secrets, no machine identifiers, no non-English text. Every defect was in what the tests would have let through, and three were re-run by the coordinating agent against a scratch copy that keeps .git, because TestInitGolden fails without one and a red baseline proves nothing. Two were blocking: the invented-route guard pinned a single literal, so a bullet describing epic reopen as sanctioned in any other phrasing passed while contradicting the section''s own closing sentence; and the segment helper located a section by first match, so a decoy heading planted earlier widened the window to swallow both, letting bait text satisfy the assertions while the real section was reversed. One material: swapping the justifications of two adjacent route bullets passed with each bullet''s own anchors intact. The absolute-path test this story introduced missed five shapes including a Windows drive path with a username, and scoped itself by file extension rather than by principle, excluding a settings file init also writes. The language section owed an acknowledgement of the asymmetry it creates and now states which of its three reasons argue for one language and which for English. A spec correction came out of the implementation rather than the review: section 6.4 recorded only the status half of the dissolve carve-out while the code and the r16 amendment''s own reasoning scope it by provenance - spec 3.42 to 3.43.', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 10, 'S7', '2026-07-26T10:57:43Z', 'IN-PROGRESS', '', '', '', NULL, '');
INSERT INTO worklog (epic, seq, story, date, state, commits, gate, review, corrects, note) VALUES ('adoption-contract', 11, 'S7', '2026-07-26T10:59:54Z', 'DONE', '0508e92..8bf79be', 'make gates exit 0 (build, vet, test -race all packages, golangci-lint 0 issues, fix-check clean, govulncheck clean, check-pins, check-copies, binaries); selftracked verify full: 0 violations. DDL byte-equality verified independently by the coordinating agent: binaries built from HEAD and from this tree emit an identical DDL block, sha 8bbb8daec5f8347b both.', 'FULL tier. Three fresh-context critics: spec fidelity and Go correctness, test adequacy by mutation, and the standing security-and-publication lens. Two lenses converged independently on the same blocking defect by different routes - one through the both-keys boundary matrix, the other by attacking message construction from untrusted input. The defect came from exceeding the spec rather than falling short of it: section 6.2 asks the corpus''s unknown-field refusal to name both spellings, and the implementation added a scope so the hint would not land on unrelated keys. encoding/json reports a rejected key''s name but not its path, so the scope was reconstructed by a second loose parse that guesses - and guessed wrong twice under measurement, once producing a sentence calling a key unknown and accepted at the same time. Security, measured by the coordinating agent: a 300000-character key produced a 300201-character refusal into the session-start channel, and after the first fix the same flood reappeared on the generic branch at 300086 bytes; both bounded. The mutation lens left one survivor: a column added to epic_criteria passed the three natural packages and was caught only incidentally by a golden in a fourth, so internal/schema now pins the DDL digest and every table''s columns. Refuted with evidence: 200000-level nesting is cut by the stdlib and degrades safely; quotes, newlines, NUL, ANSI escapes and invalid UTF-8 in a key keep the error well-formed with no raw control bytes emitted; no nil dereference on any pointer-field shape including explicit nulls; duplicate keys and a BOM do not desynchronize the two parses. INCIDENT during the round, filed as #86: a critic put 5006 synthetic epics into this repository''s tracker through load - 78 MB dump, 305886 lines against 879 - and the absolute-path instruction that #82 produced was in its brief and could not have helped, because load --force names no path at all and resolves the tracker from the working directory. Found because verify stopped returning, not from the agent''s report.', NULL, '');
