INSERT INTO events (seq, at, entity, event, detail) VALUES (153, '2026-07-25T14:32:11Z', '#33', 'set-status', 'Owner verdict 2026-07-25: adopt A2 - R13 counts only live homes; an archived home is history, not a home. Ratified on the revision-2 research document (docs/research/2026-07-25-terminal-epic-and-archived-home-semantics.md). Implementation travels amendment r13-counts-live-homes; this task closes when the amendment and its code land with green gates.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (154, '2026-07-25T14:32:11Z', '#35', 'set-status', 'Owner verdict 2026-07-25: adopt B2 then B1, B4 deferred - a terminal epic''s closure is a claim that must stay true (detection rule) and its record is write-locked against the verbs that re-open close conditions, with the repair paths carved out. Ratified on the revision-2 research document. Implementation travels two amendments; this task closes with them.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (155, '2026-07-25T14:45:13Z', '#50', 'create', 'The rule-fixture coverage gate is not mechanized against the engine');
INSERT INTO events (seq, at, entity, event, detail) VALUES (156, '2026-07-25T14:45:28Z', '#33', 'set-status', 'R13 counts live homes only (amendment r13-counts-live-homes, spec rev 3.26). Evidence: rules_fs.go r13 joins artifacts on archived=0; two new verify tests (archived-only home flagged, live-beside-archived not flagged); go test ./... green; make gates exit 0.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (157, '2026-07-25T14:45:28Z', '#35', 'set-status', 'Answered and implemented: a terminal epic''s closure is a claim verify re-checks (R16, amendment terminal-epic-conditions-stay-true, rev 3.27) and its record is write-locked against the verbs that reopen close conditions, with V-rows, corrections, artifact links and --detach carved out (amendment terminal-epics-refuse-reopening-writes, rev 3.28). criteria add on a terminal epic now refuses. Evidence: terminal-epic.txtar end-to-end; three R16 verify tests incl. the import exemption; go test ./... green; make gates exit 0.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (158, '2026-07-25T14:45:28Z', '#48', 'set-status', 'Closed by the same two amendments: 13 verb paths guarded (criteria add/met, story add, every story transition incl. start''s own path, create --epic, edit --epic, reopen of a homed task, epic goal and story-field edits), and R16 detects what arrives by import or raw SQL. Evidence: terminal-epic.txtar asserts each refusal by code and message; go test ./... green; make gates exit 0.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (159, '2026-07-25T14:45:28Z', '#49', 'set-status', 'criteria check on a terminal epic is now report-only: it runs, prints results and its own ''results reported, not recorded'' line, exits 1 on failure, and writes nothing - the close-time evidence survives. Evidence: terminal-epic.txtar asserts the PASS evidence stays in the dump while the check reports FAIL; go test ./... green; make gates exit 0.');
