INSERT INTO events (seq, at, entity, event, detail) VALUES (200, '2026-07-25T20:18:07Z', 'epic:tracking-integrity', 'criteria', 'add: The recording dead zone is resolved: work that legitimately falls under an epic whose stories are all terminal either has a sanctioned record, or meets a refusal that names the alternative and the choice belonging to the owner');
INSERT INTO events (seq, at, entity, event, detail) VALUES (201, '2026-07-25T20:18:07Z', 'epic:tracking-integrity', 'criteria', 'add: Every change to a surface the spec describes landed through an accepted OpenSpec change proposal before its code merged, with tests and green gates');
INSERT INTO events (seq, at, entity, event, detail) VALUES (202, '2026-07-25T20:18:19Z', 'epic:adoption-contract', 'epic', 'create: Make the materials that init installs sufficient for a fresh agent''s first hour. Today the generated contract describes the verbs but never says how to invoke the tool, which tracker it is operating on, whether new work is a task or a story, what language its content should be in, or that a whole class of writes is refused against a closed epic; the migration guide documents neither the md-table format nor the remote a rehearsal copy inherits. Every item was hit in practice during the pilot rehearsals.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (203, '2026-07-25T20:18:19Z', 'epic:adoption-contract', 'criteria', 'add: A fresh agent working only from the installed materials can determine how to invoke the tool, which tracker a verb operates on, and whether new work belongs as a standalone task or a story under an epic');
INSERT INTO events (seq, at, entity, event, detail) VALUES (204, '2026-07-25T20:18:19Z', 'epic:adoption-contract', 'criteria', 'add: Every refusal class an adopter can meet in the first hour is named in the generated contract, the terminal-epic class among them, together with its sanctioned routes');
INSERT INTO events (seq, at, entity, event, detail) VALUES (205, '2026-07-25T20:18:19Z', 'epic:adoption-contract', 'criteria', 'add: The migration guide documents the md-table format it offers, and makes severing the inherited remote the first act on a copy-on-write rehearsal copy');
