INSERT INTO events (seq, at, entity, event, detail) VALUES (245, '2026-07-25T22:38:37Z', '#58', 'set-status', 'Closed by story S2 of epic tracking-integrity, commit db6db4b. Both refusals now name the routes that apply in the epic''s current state; the dead zone still admits no write, and that limit is stated in the accepted amendment rather than papered over. Evidence: make gates exit 0; internal/cli/testdata/worklog.txtar asserts all four story statuses, the dead zone, the unknown epic, and the two reordered pipeline refusals; internal/verb/worklog_test.go asserts each clause as a whole string.');
