INSERT INTO events (seq, at, entity, event, detail) VALUES (250, '2026-07-25T23:26:02Z', '#59', 'set-status', 'Closed by story S3 of epic tracking-integrity, commit 495cae6. R10 reports an ACTIVE epic with no story in a non-terminal status at once, independent of idle_days, and runs on the --fast partition; --quiet now prints a one-line advisory summary to stderr, so the condition reaches the commit boundary instead of being computed and discarded there. Evidence: make gates exit 0; internal/cli/testdata/hook-advisory-line.txtar drives a real git commit through the installed hook and observes the line; TestRuleFixtureCoverage''s R10 fixture seeds a homeless-not-idle and an idle-not-homeless epic, so deleting either trigger turns the mandatory gate red - re-run and confirmed.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (251, '2026-07-25T23:26:02Z', '#60', 'set-status', 'Closed by story S3 of epic tracking-integrity, commit 495cae6. Every R16 clause names its repair; the story clause gained one - story dissolve of a non-terminal story on an epic this tracker closed by verb. Scoped by provenance, not status: an epic that arrived CLOSED through import is silent to R16 and refuses the repair, and one fixture asserts both together because their agreement is the property. The criterion clause is named as what it now is - a state no verb writes, reachable only by raw SQL. Evidence: make gates exit 0; the coordinator reproduced the full round trip (R16 reports, the named repair runs, R16 goes silent) and the refusal of the import-arrived case, before and after the narrowing.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (252, '2026-07-25T23:26:02Z', 'epic:tracking-integrity/S3', 'story', 'done: 495cae6; gate: make gates exit 0 (2026-07-25)');
