INSERT INTO events (seq, at, entity, event, detail) VALUES (256, '2026-07-26T00:01:00Z', '#66', 'set-status', 'Closed by story S4 of epic tracking-integrity, commit fa5dbb2. prime carries a typed no-workable-story notice in the JSON the SessionStart hook reads and renders it as a sentence in the human digest; stories.planned joined the tally so the notice''s silence is not the only signal. Evidence: make gates exit 0; a fidelity critic verified prime''s notices and verify''s R10 homeless clause agree across every story status (none, PLANNED, DONE, BLOCKED, DISSOLVED); the emitted JSON key order was checked against section 11.1''s stated field position, not the struct declaration.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (257, '2026-07-26T00:01:00Z', '#55', 'set-status', 'Closed by story S4 of epic tracking-integrity, commit fa5dbb2. The generated contract states when new work is a task and when it is a story, that opening a story is a scope change the owner authorizes, and reconciles that rule with the drift rule the skill already shipped. This repository''s own PROMPT.md and installed skill carry the same text, byte-identical to their templates - the task was filed because this repository''s agent guessed, so a template-only change would have closed it without fixing that. Evidence: make gates exit 0; content tests pin both texts and both cross-references; cmp confirms the three root copies match their templates.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (258, '2026-07-26T00:01:00Z', 'epic:tracking-integrity/S4', 'story', 'done: fa5dbb2; gate: make gates exit 0 (2026-07-26)');
INSERT INTO events (seq, at, entity, event, detail) VALUES (259, '2026-07-26T00:01:22Z', 'epic:tracking-integrity', 'criteria', 'check: 0 line(s), failed=false');
INSERT INTO events (seq, at, entity, event, detail) VALUES (260, '2026-07-26T00:22:40Z', 'epic:tracking-integrity', 'criteria', 'met 1: PO 2026-07-26: attested on the v0 scope the owner set in #61. prime names the epic-scoped instance - an ACTIVE epic with no story that can receive work - as a typed no-workable-story notice in the JSON the SessionStart hook reads, and as a sentence in the digest. Work matching no epic at all is NOT detected by any tool output: that is the v0.1 interactive protocol (#61, parked), and this criterion''s wording is broader than v0 delivers. Attested with the narrowing on the record because no verb can edit a criterion (#65). Evidence: commit fa5dbb2; make gates exit 0.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (261, '2026-07-26T00:22:40Z', 'epic:tracking-integrity', 'criteria', 'met 2: Both refusals met in the dead zone name the routes that apply in the epic''s current state, and mark the story route as a scope change the owner authorizes. Evidence: commit db6db4b; the coordinator reproduced the WIP-slot defect before the fix and the corrected advice after; make gates exit 0.');
