INSERT INTO events (seq, at, entity, event, detail) VALUES (325, '2026-07-26T07:02:11Z', '#80', 'create', 'The drift gate''s regular-file check tests the last path component only');
INSERT INTO events (seq, at, entity, event, detail) VALUES (326, '2026-07-26T07:02:11Z', '#68', 'set-status', 'Closed by story S6 2026-07-26. make gates now runs scripts/check-installed-copies.sh, which fails when any of the three installed generated documents differs byte-for-byte from the template it ships, and scripts/check-installed-copies-fixture.sh, which proves the comparison can fail before it reports that it did not. Evidence, all commands run by the coordinating agent rather than reported by the implementer: the gate against a scratch tree built from the real templates exits 0 on identity, 1 on a single appended byte in the third pair, and 1 with a missing copy - naming both drifted pairs in one run; an emptied pair table exits 1 rather than reporting zero comparisons as a pass; a symlink standing in for an installed copy with byte-identical content exits 1; a pair row containing a .. component is refused at --list, before the fixture can build anything outside its temp tree; an empty ROOT argument exits 1 while an absent one still defaults to the repository root. A fix round preceded this close: three critics under distinct lenses found the empty-table and symlink holes, an escape from the fixture''s own sandbox, and a false count in the amendment''s text. make gates exits 0; verify full reports 0 violations.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (327, '2026-07-26T07:03:03Z', 'epic:adoption-contract/S6', 'story', 'done: 8d28dfe..7b12738; gate: make gates exit 0 (now including check-copies: the red fixture then the byte-for-byte comparison); selftracked verify full: 0 violations. Gate proven by the coordinating agent against a scratch tree, not by the implementer''s report: identity 0; one appended byte in the third pair 1; missing copy 1, both drifted pairs named in one run; emptied pair table 1; symlink with identical content 1; a .. row refused at --list; empty ROOT 1, absent ROOT 0.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (328, '2026-07-26T07:04:20Z', '#78', 'set-status', 'Closed 2026-07-26 by adding the step to the policy job of .github/workflows/ci.yml - the fixture first, then the comparison, mirroring make check-copies. Scope of the fix stated honestly: CI still does NOT call make gates. Its gates job remains a hand-rolled subset (verified 2026-07-26 by parsing the workflow: checkout, setup-go, build, vet, test, lint, modern idiom, vulnerabilities - no check-pins, no binaries, no check-copies), and the policy job still enumerates scripts individually. What changed is that the installed-copy drift check now runs on every commit that reaches CI rather than only for whoever types make locally, which was the half of the amendment''s purpose this task named. The larger question - whether CI should call make gates instead of re-implementing it, so the two cannot drift - is untouched and is not this task. Verified before closing: the workflow still parses and the new step appears in the policy job''s step list; git records both scripts as mode 100755, so the checkout gets them executable; both parse and run to completion under dash, which is /bin/sh on the ubuntu runner.');
INSERT INTO events (seq, at, entity, event, detail) VALUES (329, '2026-07-26T07:04:20Z', '#81', 'create', 'CI re-implements make gates by hand instead of calling it, so the two can drift');
